from PyQt5.QtCore import Qt, QTimer, QPointF, QRectF, QElapsedTimer
from PyQt5.QtGui import QPainter, QColor, QPen, QImage, QTransform, QPolygonF, QFont
from PyQt5.QtWidgets import QApplication, QWidget, QPushButton, QComboBox

C, S = 0.8660254, 0.5
LV = [1, 2, 3, 4, 5, 7, 8]
NM = ['Pez espada', 'Cangrejo', 'Escorpión', 'Camarón mantis', 'Estrella', 'Ciempiés', 'Pulpo']


def decode(url): return QImage.fromData(base64.b64decode(url.split(',', 1)[1]))
def col(r, g, b, a=1.0): return QColor(r, g, b, int(a * 255))
def pen(r, g, b, a=1.0, w=1): return QPen(col(r, g, b, a), w)


class Set:
    def __init__(me, d):
        me.dim = d['dim']; me.piv = d.get('piv', {}); me.m = {k: decode(v) for k, v in d['img'].items()}


def sprite_nave(ang):
    img = QImage(40, 40, QImage.Format_ARGB32); img.fill(0)
    p = QPainter(img); p.setPen(Qt.NoPen)
    p.translate(20, 20); p.rotate(math.degrees(ang)); p.translate(-16, -8)
    def poly(c, pts):
        p.setBrush(QColor(*c)); p.drawPolygon(QPolygonF([QPointF(x, y) for x, y in pts]))
    poly((42, 92, 208), [(15, 6), (7, 0), (3, 0), (8, 6)])
    poly((60, 130, 255), [(16, 10), (8, 16), (2, 16), (7, 10)])
    poly((140, 150, 200), [(32, 8), (12, 11), (4, 10), (4, 8)])
    poly((200, 205, 234), [(32, 8), (12, 5), (4, 6), (4, 8)])
    poly((80, 230, 255), [(24, 7.4), (18, 5.6), (18, 8)])
    p.fillRect(QRectF(1, 6.5, 3, 3), QColor(80, 230, 255)); p.end()
    for y in range(40):
        for x in range(40):
            c = img.pixel(x, y)
            img.setPixel(x, y, (c | 0xFF000000) if ((c >> 24) & 255) > 110 else 0)
    return img


class Ventana(QWidget):
    def __init__(me):
        super().__init__()
        me.setWindowTitle('ABISAL'); me.resize(1100, 760); me.setMinimumSize(640, 480)
        me.setFocusPolicy(Qt.StrongFocus)
        me.g = Juego()
        me.sets = {k: Set(ASSETS[k]) for k in ('PZD', 'PCAN', 'PPEZ', 'PMAN', 'PEST', 'PPUL', 'PGUS')}
        me.mini = decode(ASSETS['PMIN']['src']); me.cover = decode(ASSETS['cover']); me.nave = sprite_nave(-.4)
        me.teclas = set(); me.pausa = False; me.acc = 0.0
        me.cs, me.ox, me.oy = 12.0, 0.0, 0.0
        # menú de título
        me.btn = QPushButton('JUGAR', me); me.cb_j = QComboBox(me); me.cb_n = QComboBox(me)
        for w_ in (me.btn, me.cb_j, me.cb_n): w_.setFocusPolicy(Qt.NoFocus)
        me.btn.setStyleSheet('QPushButton{background:#1d6bff;color:white;font:bold 18px;border:2px solid #7fe6ff;border-radius:10px}QPushButton:hover{background:#3d86ff}')
        est = 'QComboBox{background:#0d1f4a;color:#bfe6ff;border:1px solid #4a78c8;border-radius:6px;padding:4px 8px;font:14px}QComboBox QAbstractItemView{background:#0d1f4a;color:#bfe6ff;selection-background-color:#1d6bff}'
        me.cb_j.setStyleSheet(est); me.cb_n.setStyleSheet(est)
        me.cb_j.addItem('Jefes', 0); me.cb_n.addItem('Niveles', 0)
        for i, l in enumerate(LV):
            me.cb_j.addItem('%d. %s' % (i + 1, NM[i]), l); me.cb_n.addItem('Nivel %d' % (i + 1), l)
        me.btn.clicked.connect(lambda *_: me.empezar(1))
        me.cb_j.activated.connect(lambda *_: me.elegir(me.cb_j, True))
        me.cb_n.activated.connect(lambda *_: me.elegir(me.cb_n, False))
        me.reloj = QElapsedTimer(); me.reloj.start()
        me.timer = QTimer(me); me.timer.timeout.connect(me.paso); me.timer.start(16)

    # --- control de partida ----------------------------------------
    def empezar(me, lv, directo=False):
        me.g.reset('j', lv)
        if directo: me.g.kills = me.g.KILLS
        me.acc = 0.0; me.teclas.clear(); me.pausa = False; me.setFocus()

    def elegir(me, cb, directo):
        lv = cb.itemData(cb.currentIndex())
        if lv: me.empezar(lv, directo)
        cb.setCurrentIndex(0)

    def continuar(me):
        g = me.g
        me.empezar(SIGUIENTE[g.lv] if g.st == 'v' else g.lv)

    def resizeEvent(me, e):
        w, h = me.width(), me.height()
        me.btn.setGeometry(w // 2 - 150, h - 150, 300, 50)
        me.cb_j.setGeometry(w // 2 - 170, h - 86, 160, 34); me.cb_n.setGeometry(w // 2 + 10, h - 86, 160, 34)

    def keyPressEvent(me, e):
        if e.isAutoRepeat(): return
        k = e.key(); g = me.g
        if k == Qt.Key_Escape:
            if g.st == 'i': me.close()
            else: g.reset('i')
        elif k == Qt.Key_F11: me.showNormal() if me.isFullScreen() else me.showFullScreen()
        elif k == Qt.Key_P and g.st == 'j': me.pausa = not me.pausa
        elif k in (Qt.Key_Space, Qt.Key_Return, Qt.Key_Enter) and g.st in ('v', 'd'): me.continuar()
        else: me.teclas.add(k)

    def keyReleaseEvent(me, e):
        if not e.isAutoRepeat(): me.teclas.discard(e.key())

    def focusOutEvent(me, e): me.teclas.clear()

    def mousePressEvent(me, e):
        if me.g.st in ('v', 'd'): me.continuar()

    def paso(me):
        dt = me.reloj.restart(); g = me.g
        if g.st != 'i' and not me.pausa:
            me.acc += min(dt, 100); k = me.teclas
            while me.acc >= TK:
                me.acc -= TK
                dx = (Qt.Key_Right in k or Qt.Key_D in k) - (Qt.Key_Left in k or Qt.Key_A in k)
                dy = (Qt.Key_Up in k or Qt.Key_W in k) - (Qt.Key_Down in k or Qt.Key_S in k)
                g.tick(dx, dy, Qt.Key_Space in k)
        me.update()

    # --- geometría isométrica --------------------------------------
    def P(me, x, y, z): return QPointF(me.ox + (x + z) * C * me.cs, me.oy + (x - z) * S * me.cs - y * me.cs)
    def L(me, p, a, b): p.drawLine(me.P(*a), me.P(*b))
    def Q(me, x, y, z, w, h): return QPolygonF([me.P(x, y, z), me.P(x + w, y, z), me.P(x + w, y + h, z), me.P(x, y + h, z)])

    def plano(me, p, img, x, yb, z, wc, hc, rot=None):
        o = me.P(x, yb + hc, z); w, h = img.width(), img.height()
        t = QTransform(C * me.cs * wc / w, S * me.cs * wc / w, 0.0, me.cs * hc / h, o.x(), o.y())
        if rot:
            pv, ang = rot; t.translate(pv[0], pv[1]); t.rotate(math.degrees(ang)); t.translate(-pv[0], -pv[1])
        p.save(); p.setTransform(t); p.drawImage(0, 0, img); p.restore()

    def pzdraw(me, p, st, jp, a, orden, wc, yo):
        hc = wc * st.dim[1] / st.dim[0]
        for k in orden:
            ang = a.get(k, 0)
            me.plano(p, st.m[k], jp[0], jp[1] + yo, jp[2] + 1, wc, hc, (st.piv[k], ang) if ang and k in st.piv else None)

    # --- jefes -----------------------------------------------------
    def dibujar_jefe(me, p, jp, j):
        g = me.g; t = g.t; s = j.s; u = j.t; JW, JH = g.JW, g.JH; sn = math.sin
        lv = g.lv
        if lv == 7:
            n = len(j.sh); st = me.sets['PGUS']
            for i, b in enumerate(j.sh):
                x, y, z = jp[0] + 3 * b[0], jp[1] + 3 * b[1], jp[2] + 1
                if s == 'aturdido':
                    p.setPen(pen(255, 230, 80, 1, 2)); p.setBrush(Qt.NoBrush); p.drawPolygon(me.Q(x, y, z, 3, 3))
                im = st.m['cab'] if (i == n - 1 and b[0] * 3 < JW / 2) else st.m['cabF'] if i == n - 1 else st.m['seg']
                w = im.width() / im.height() * 3
                me.plano(p, im, x + (3 - w) / 2, y, z, w, 3)
        elif lv == 3:
            a = {'cola': sn(t / 6) * .06, 'pizq': sn(t / 5) * .08, 'pfr': -sn(t / 5) * .08}
            if s == 'pica': a['cola'] = .05 + u * .04 if u < 9 else -.55
            elif s in ('aviso', 'carga'): a['pizq'] = a['pfr'] = .25
            elif s == 'garra': a['pizq'] = sn(t / 2) * .3; a['pfr'] = sn(t / 2 + 1.5) * .3
            me.pzdraw(p, me.sets['PZD'], jp, a, ['cuerpo', 'pizq', 'pfr', 'cola'], JW, 0)
        elif lv == 2:
            a = {'pizq': sn(t / 5) * .06, 'pfr': -sn(t / 5) * .06, 'patas': sn(t / 4) * .03}
            if s == 'garra': a['pizq'] = sn(t / 2) * .3; a['pfr'] = sn(t / 2 + 1.6) * .3; a['patas'] = sn(t) * .05
            elif s == 'total':
                v = .15 + u * .02 if u < 14 else -.3
                a['pizq'] = a['pfr'] = v; a['patas'] = .06 if u < 14 else -.05
            elif s == 'aturdido': a['pizq'] = a['pfr'] = -.15
            me.pzdraw(p, me.sets['PCAN'], jp, a, ['cuerpo', 'patas', 'pizq', 'pfr'], JW, 0)
        elif lv == 4:
            st = me.sets['PMAN']; hc = JW * st.dim[1] / st.dim[0]
            a = {'antenas': sn(t / 4) * .07, 'cola': sn(t / 5) * .06, 'ga1': sn(t / 6) * .04, 'ga2': -sn(t / 6) * .04}
            if s == 'punch': a['ga2' if int(u / 6) % 2 else 'ga1'] = -.45 if u % 6 < 3 else .1
            elif s == 'pica': a['ga1'] = a['ga2'] = -.4
            elif s in ('aviso', 'carga'): a['ga1'] = a['ga2'] = .25
            me.pzdraw(p, st, jp, a, ['cuerpo', 'cola', 'antenas', 'ga1', 'ga2'], JW, (JH - hc) / 2)
        elif lv == 5:
            st = me.sets['PEST']; hc = JW * st.dim[1] / st.dim[0]
            ang = t * .7 if s == 'carga' else t * .2 if s == 'balas' else sn(t * 1.5) * .12 if s == 'aviso' else 0 if s == 'aturdido' else sn(t / 9) * .1
            me.pzdraw(p, st, jp, {'cuerpo': ang}, ['cuerpo'], JW, (JH - hc) / 2)
        elif lv == 8:
            st = me.sets['PPUL']; im = st.m['cuerpo']; d = st.dim; hc = JW * d[1] / d[0]
            am = 7 if s in ('garra', 'total', 'pica') else 1 if s == 'aturdido' else 3.5; cx = d[0] / 2
            o = me.P(jp[0], jp[1] + (JH - hc) / 2 + hc, jp[2] + 1)
            p.save(); p.setTransform(QTransform(C * me.cs * JW / d[0], S * me.cs * JW / d[0], 0.0, me.cs * hc / d[1], o.x(), o.y()))
            for x in range(0, d[0], 4):
                k = abs(x - cx) / cx
                p.drawImage(QRectF(x, sn(t / 4 + x * .07) * am * k, 4, d[1]), im, QRectF(x, 0, 4, d[1]))
            p.restore()
        else:
            st = me.sets['PPEZ']; hc = JW * st.dim[1] / st.dim[0]
            a = {'cola': 0 if s == 'carga' else sn(t / 3) * .12, 'aleta': 0 if s == 'carga' else sn(t / 4) * .1}
            me.pzdraw(p, st, jp, a, ['cuerpo', 'aleta', 'cola'], JW, (JH - hc) / 2)
        if s == 'aturdido' and lv != 7:
            p.setPen(pen(255, 230, 80, .9)); p.setBrush(Qt.NoBrush); p.drawPolygon(me.Q(jp[0], jp[1], jp[2] + 1, JW, JH))

    # --- escena ----------------------------------------------------
    def jaula(me, p):
        t = pen(50, 90, 150, .4); m = pen(70, 130, 210, .8)
        for x in range(W + 1):
            p.setPen(t); me.L(p, (x, 0, 0), (x, 0, D)); me.L(p, (x, 0, D), (x, H, D))
        for z in range(D + 1):
            p.setPen(t if z % 8 else m); me.L(p, (0, 0, z), (W, 0, z)); me.L(p, (0, 0, z), (0, H, z))
        for y in range(H + 1):
            p.setPen(t); me.L(p, (0, y, 0), (0, y, D)); me.L(p, (0, y, D), (W, y, D))
        p.setPen(pen(80, 200, 255, .4))
        for i in range(W + 1): me.L(p, (i, 0, 0), (i, H, 0)); me.L(p, (0, i, 0), (W, i, 0))
        p.setPen(pen(120, 220, 255, .9, 2)); p.setBrush(Qt.NoBrush); p.drawPolygon(me.Q(0, 0, 0, W, H))

    def zdib(me, p):
        g = me.g; p.setBrush(Qt.NoBrush)
        for z in g.zn:
            x, y, w, h = z['r']
            p.setPen(pen(255, 60, 60, .8, 2)); p.setBrush(col(255, 60, 60, .15 + .2 * (g.t % 2))); p.drawPolygon(me.Q(x, y, 0, w, h))
            p.setPen(Qt.NoPen); p.setBrush(col(80, 255, 140, .5))
            for o in z.get('h', []): p.drawPolygon(me.Q(o[0], o[1], 0, 2, 2))
        for q in g.s:
            if q.ph and getattr(q, 'lk', None):
                p.setPen(pen(255, 90, 60, .5)); me.L(p, (q.x, q.y, q.z), (q.lk[0] + .5, q.lk[1] + .5, 0))
                p.setPen(Qt.NoPen); p.setBrush(col(255, 90, 60, .2 + .2 * (g.t % 2))); p.drawPolygon(me.Q(q.lk[0], q.lk[1], 0, 1, 1))
        p.setPen(Qt.NoPen); p.setBrush(col(255, 255, 255, .55))
        for f in g.fl: p.drawPolygon(me.Q(f[0][0], f[0][1], 0, f[0][2], f[0][3]))

    def punto(me, p, x, y, z, r, c):
        pt = me.P(x, y, z); p.setPen(Qt.NoPen)
        p.setBrush(col(*c, .28)); p.drawEllipse(pt, r * 1.9, r * 1.9)
        p.setBrush(col(*c)); p.drawEllipse(pt, r, r)

    def dibujar_titulo(me, p, w, h):
        sc = min(w / 960, (h - 130) / 540); rw, rh = 960 * sc, 540 * sc
        p.setRenderHint(QPainter.SmoothPixmapTransform, True)
        p.drawImage(QRectF((w - rw) / 2, 10, rw, rh), me.cover)
        p.setRenderHint(QPainter.SmoothPixmapTransform, False)
        p.setPen(QColor(120, 160, 220)); p.setFont(QFont('Monospace', 10))
        p.drawText(QRectF(0, h - 40, w, 30), Qt.AlignCenter, 'flechas / WASD mover · ESPACIO disparar · P pausa · ESC menú · F11 pantalla completa')

    def paintEvent(me, ev):
        g = me.g; p = QPainter(me); w, h = me.width(), me.height()
        p.fillRect(me.rect(), QColor(11, 10, 24))
        titulo = g.st == 'i'
        for w_ in (me.btn, me.cb_j, me.cb_n): w_.setVisible(titulo)
        if titulo:
            me.dibujar_titulo(p, w, h); p.end(); return
        me.cs = min(w * .96 / (48 * C), (h - 110) / 40); me.ox = (w - 48 * C * me.cs) / 2; me.oy = 70 + 32 * me.cs
        cs = me.cs; a = min(1.0, me.acc / TK); j = g.j
        me.jaula(p)
        jp = j.pos(a); npos = g.n.pos(a); todo = g.b + g.e + g.m + g.s
        # sombras y líneas al suelo
        p.setPen(Qt.NoPen); p.setBrush(col(0, 0, 0, .45))
        if j.s not in ('muerto', 'espera'):
            p.drawPolygon(QPolygonF([me.P(jp[0] + u, 0, jp[2] + v) for u, v in ((0, 0), (g.JW, 0), (g.JW, JD), (0, JD))]))
        for o in todo:
            x, y, z = o.pos(a); p.drawEllipse(me.P(x, 0, z), 4 * cs / 9, 2 * cs / 9)
        p.setPen(pen(120, 160, 220, .25))
        for o in todo:
            x, y, z = o.pos(a); me.L(p, (x, y, z), (x, 0, z))
        me.L(p, tuple(npos), (npos[0], 0, npos[2]))
        # avisos
        for b in g.e:
            x, y, z = b.pos(a); p.setPen(pen(255, 90, 60, .4)); me.L(p, (x, y, z), (b.tx, b.ty, 0))
            p.setPen(Qt.NoPen); p.setBrush(col(255, 90, 60, .25)); p.drawPolygon(me.Q(int(b.tx), int(b.ty), 0, 1, 1))
        if j.s in ('aviso', 'carga'):
            lx, ly = j.lk
            p.setPen(pen(255, 60, 60, .7)); p.setBrush(col(255, 60, 60, .3 + .25 * (g.t % 2)))
            for r in g.huella(): p.drawPolygon(me.Q(r[0], r[1], 0, r[2], r[3]))
            for cx_, cy_ in ((lx, ly), (lx + g.JW, ly), (lx + g.JW, ly + g.JH), (lx, ly + g.JH)):
                me.L(p, (cx_, cy_, 0), (cx_, cy_, j.z))
        me.zdib(p)
        # objetos de lejos a cerca
        items = []
        for o in todo:
            x, y, z = o.pos(a); items.append((z - x - y, o))
        if j.s not in ('muerto', 'espera'): items.append((jp[2] + 1 - jp[0] - 1.5 - jp[1] - 1, j))
        items.sort(key=lambda it: -it[0])
        for _, o in items:
            if o is j: me.dibujar_jefe(p, jp, j); continue
            x, y, z = o.pos(a)
            if hasattr(o, 'k'):
                wc = 2.6; me.plano(p, me.mini, x - 1.3, y - .64, z, wc, wc * me.mini.height() / me.mini.width())
            elif hasattr(o, 'vx'): me.punto(p, x, y, z, 4, (255, 120, 60))
            elif hasattr(o, 't'): me.punto(p, x, y, z, 6, (255, 70, 200))
            else: me.punto(p, x, y, z, 3, (80, 230, 255))
        # nave
        if not (g.inv > 0 and (g.t >> 1) % 2 == 0) and g.st != 'd':
            pt = me.P(npos[0], npos[1], 0); wv = 4.2 * cs
            p.setPen(pen(80, 230, 255, .9, 1.5)); p.setBrush(Qt.NoBrush); p.drawPolygon(me.Q(npos[0] - .5, npos[1] - .5, 0, 1, 1))
            p.drawImage(QRectF(pt.x() - wv / 2, pt.y() - wv / 2, wv, wv), me.nave)
        # efectos
        p.setPen(Qt.NoPen)
        for x, y, z, t, mx, c in g.fx:
            r = (4 + 14 * (1 - t / mx)) * cs / 9
            p.setBrush(col(*c, t / mx * .85)); p.drawEllipse(me.P(x, y, z), r, r)
        me.hud(p, w, h)
        p.end()

    def hud(me, p, w, h):
        g = me.g; j = g.j
        f = QFont('Monospace', 12); f.setBold(True); p.setFont(f)
        p.setPen(QColor(159, 212, 255))
        p.drawText(16, 28, 'ETAPA %d/7 · NAVE %s%s' % (ETAPA[g.lv], '■' * g.vida, '□' * (VN - g.vida)))
        frac = g.kills / g.KILLS if g.ph == 'olas' else max(0, j.hp) / g.VJ
        c = (80, 180, 255) if g.ph == 'olas' else (255, 90, 90) if g.furia() else (255, 170, 70)
        p.setPen(pen(90, 110, 160)); p.setBrush(Qt.NoBrush); p.drawRect(16, 38, 280, 10)
        p.setPen(Qt.NoPen); p.setBrush(col(*c)); p.drawRect(17, 39, int(278 * min(1, frac)), 8)
        M = {'aviso': '¡EMBESTIDA!', 'aturdido': '¡EXPUESTO! daño x2', 'alinear': 'se alinea…', 'misiles': 'MISILES: dispárales',
             'balas': 'RÁFAGA', 'garra': 'PINZAS', 'pica': '¡AGUIJÓN! esquiva de lado', 'punch': 'GOLPES RÁPIDOS',
             'total': '¡ATAQUE TOTAL! busca el hueco verde'}
        if g.st == 'j':
            if g.ph == 'olas': msg = 'OLEADA %d/%d' % (g.kills, g.KILLS)
            elif j.s == 'entrada': msg = '¡JEFE! ' + NOMBRES[g.lv]
            else: msg = M.get(j.s, '') + (' · FURIA' if g.furia() else '')
            p.setPen(QColor(255, 106, 106)); p.drawText(16, 72, msg)
        if g.st in ('v', 'd'):
            p.fillRect(me.rect(), QColor(5, 5, 15, 180))
            f2 = QFont('Monospace', 24); f2.setBold(True); p.setFont(f2); p.setPen(QColor(159, 212, 255))
            t1 = '¡ABISAL COMPLETADO!' if (g.st == 'v' and g.lv == 8) else '¡VICTORIA!' if g.st == 'v' else 'DERROTA'
            t2 = 'ESPACIO o clic para jugar de nuevo' if (g.st == 'v' and g.lv == 8) else 'ESPACIO o clic para la siguiente etapa' if g.st == 'v' else 'ESPACIO o clic para reintentar'
            p.drawText(QRectF(0, h / 2 - 50, w, 50), Qt.AlignCenter, t1)
            f3 = QFont('Monospace', 13); p.setFont(f3); p.drawText(QRectF(0, h / 2 + 10, w, 30), Qt.AlignCenter, t2)
        if me.pausa:
            p.setPen(QColor(255, 255, 255)); p.drawText(QRectF(0, h / 2 - 20, w, 40), Qt.AlignCenter, 'PAUSA')


if __name__ == '__main__':
    app = QApplication(sys.argv)
    v = Ventana(); v.show()
    sys.exit(app.exec_())
